char text[3] = " O";
/* count neighbors of cell (i,j) in world g */
size_t nbrCount(size_t i, size_t j, const vector<vector<bool> >& g)
{
	size_t rows = world.size();
	size_t cols = world[0].size();
	/* eight locations to check. */
	bool self = g[i][j]; /* so we can subtract it off later. */
	size_t count = 0;
	/* NOTE: assumes #cols and #rows > 2 */
	for (int k = rows-1; k != 2; k=(k+1)%rows) {
		for (int l = cols-1; l != 2; l=(l+1)%cols) {
			// if (g[(i+k) % rows][(j+l)%cols]) count++;
			count += g[(i+k) % rows][(j+l)%cols];
		}
	}
	return count - self;
	/* NOTE: again we use the fact that true will cast to (int)1. */
}

void printState()
{
	size_t rows = world.size();
	size_t cols = world[0].size();
	char newline[2] = "\n";
	for (size_t i = 0; i < rows; i++) {
		for (size_t j = 0; j < cols; j++) {
			printf("%c",text[world[i][j]]);
		}
		printf("\n");
	}
}

/* Just for fun, above is a more interesting configuration for the cells.
 * You can mostly copy your code from warmup.cpp here to try it out.  Note
 * the changes suggested below (using sleep to animate). */
int main()
{
	size_t rows = world.size();
	size_t cols = world[0].size();
	/* to draw some nicer, animated pictures, proceed as follows: */
	while (true) {
		/* print the current state of the world */
		printState();
		/* allocate some scratch space to figure out what will happen next: */
		vector<vector<bool>> future(world); /* NOTE: copying world just gets the dimensions right.
		                                       We didn't actually need to copy the values. */
		/* apply rules, writing result to future */
		/* ...your code goes here... */
		for (size_t i = 0; i < rows; i++) {
			for (size_t j = 0; j < cols; j++) {
				size_t nnbrs = nbrCount(i,j,world);
				if (world[i][j]) { // it's alive
					if (nnbrs < 2 || nnbrs > 3) future[i][j] = false;
					else future[i][j] = true;
				} else { // dead
					if (nnbrs == 3) future[i][j] = true;
					else future[i][j] = false;
				}
			}
		}
		/* now that the future is computed, overwrite world, and then sleep */
		world = future;
		sleep(1);
	}
	return 0;
}
